     document.getElementById("chat-modal").style.display = "none";
   }

   // Event listeners
   document.getElementById("open-chat-modal").addEventListener("click", openModal);
   document.getElementById("chat-modal").addEventListener("click", (event) => {
     if (event.target.id === "chat-modal") {
       closeModal();
     }
   });
   ```

5. Agregar el contenido del modal con el historial de chat falso:

